import{_ as s,W as i,s as r,u as p,ah as g,I as t,Z as a,w as e,A as l}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const k=JSON.parse('{"title":"如何在 Kali Linux 中安装 Google Chrome 浏览器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Kali Linux 中安装 Google Chrome 浏览器 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 Kali Linux 中安装 Google Chrome 浏览器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Kali Linux 中安装 Google Chrome 浏览器 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170121 How to install Google Chrome Browser on Kali Linux","title":"如何在 Kali Linux 中安装 Google Chrome 浏览器","tag":"201702"},"relativePath":"201702/20170121 How to install Google Chrome Browser on Kali Linux.md","filePath":"[post].md"}'),d={name:"201702/20170121 How to install Google Chrome Browser on Kali Linux.md"};function u(h,o,m,c,b,x){const n=i("Link");return p(),r("div",null,[o[15]||(o[15]=g(`<h1 id="如何在-kali-linux-中安装-google-chrome-浏览器" tabindex="-1">如何在 Kali Linux 中安装 Google Chrome 浏览器 <a class="header-anchor" href="#如何在-kali-linux-中安装-google-chrome-浏览器" aria-label="Permalink to 如何在 Kali Linux 中安装 Google Chrome 浏览器">​</a></h1><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to 介绍">​</a></h3><p><strong>目的</strong></p><p>我们的目标就是在 Kali Linux 上安装好 Google Chrome Web 浏览器。同时，请参阅附录为可能出现的问题进行排查。</p><p><strong>要求</strong></p><p>需要获得已安装 Kali Linux 或者 Live 系统的特权。</p><p><strong>困难程度</strong></p><p>容易。</p><p><strong>惯例</strong></p><ul><li><code>#</code> - 给定命令需要以 root 用户权限运行或者使用 <code>sudo</code> 命令</li><li><code>$</code> - 给定命令以常规权限用户运行</li></ul><h3 id="步骤说明" tabindex="-1">步骤说明 <a class="header-anchor" href="#步骤说明" aria-label="Permalink to 步骤说明">​</a></h3><p><strong>下载 Google Chrome</strong></p><p>首先，使用 <code>wget</code> 命令来下载最新版本的 Google Chrome 的 debian 安装包。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># wget https://dl.google.com/linux/direct/google-chrome-stable_current_amd64.deb</span></span></code></pre></div><p><strong>安装 Google Chrome</strong></p><p>在 Kali Linux 安装 Google Chrome 最容易的方法就是使用 <code>gdebi</code>，它会自动帮你下载所有的依赖包。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># gdebi google-chrome-stable_current_amd64.deb</span></span></code></pre></div><p><strong>启动 Google Chrome</strong></p><p>开启一个终端（terminal），执行 <code>google-chrome</code> 命令来启动 Google Chrome 浏览器。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ google-chrome</span></span></code></pre></div><h3 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to 附录">​</a></h3><p><strong>非法指令 (Illegal Instruction)</strong></p><p>当以 root 用户特权来运行 <code>google-chrome</code> 命令是，会出现 非法指令 (Illegal Instruction) 错误信息。因为通常情况下，Kali Linux 默认情况下的默认用户是 root 用户，我们需要创建一个虚的非特权用户，比如 <code>linuxconfig</code>，然后使用这个用户来启动 Google Chrome 浏览器。如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># useradd -m -d /home/linuxconfig linuxconfig</span></span>
<span class="line"><span># su linuxconfig -c google-chrome</span></span></code></pre></div><p><strong>libappindicator1 包未安装</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dpkg: dependency problems prevent configuration of google-chrome-stable:</span></span>
<span class="line"><span> google-chrome-stable depends on libappindicator1; however:</span></span>
<span class="line"><span>  Package libappindicator1 is not installed.</span></span></code></pre></div><p>使用 <code>gdebi</code> 命令来安装 Google Chrome 的 debian 包可以解决依赖问题。参阅上文。</p><p><img src="https://linuxconfig.org/images/kali-linux-google-chome-browser-start.jpg" alt="在 Kali Linux 中以普通用户启动 google chrome"></p><hr><p>译者简介：</p>`,30)),t("p",null,[a(n,{href:"http://GHLandy.com"},{default:l(()=>o[0]||(o[0]=[e("GHLandy")])),_:1}),o[1]||(o[1]=e(" —— 生活中所有欢乐与苦闷都应藏在心中，有些事儿注定无人知晓，自己也无从说起。"))]),o[16]||(o[16]=t("hr",null,null,-1)),t("p",null,[o[3]||(o[3]=e("via: ")),a(n,{href:"https://linuxconfig.org/how-to-install-google-chrome-browser-on-kali-linux"},{default:l(()=>o[2]||(o[2]=[e("https://linuxconfig.org/how-to-install-google-chrome-browser-on-kali-linux")])),_:1})]),t("p",null,[o[7]||(o[7]=e("作者：")),a(n,{href:"https://linuxconfig.org/how-to-install-google-chrome-browser-on-kali-linux"},{default:l(()=>o[4]||(o[4]=[e("Lubos Rendek")])),_:1}),o[8]||(o[8]=e(" 译者：")),a(n,{href:"https://github.com/GHLandy"},{default:l(()=>o[5]||(o[5]=[e("GHLandy")])),_:1}),o[9]||(o[9]=e(" 校对：")),a(n,{href:"https://github.com/wxy"},{default:l(()=>o[6]||(o[6]=[e("wxy")])),_:1})]),t("p",null,[o[12]||(o[12]=e("本文由 ")),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>o[10]||(o[10]=[e("LCTT")])),_:1}),o[13]||(o[13]=e(" 原创编译，")),a(n,{href:"https://linux.cn/"},{default:l(()=>o[11]||(o[11]=[e("Linux中国")])),_:1}),o[14]||(o[14]=e(" 荣誉推出"))])])}const v=s(d,[["render",u]]);export{k as __pageData,v as default};
